package com.autocare.platform.order;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"JWT_SECRET=test-only-secret-with-at-least-32-characters"}) @AutoConfigureMockMvc class CommunityQuestionHttpTest {
 @Autowired MockMvc mvc;@MockitoBean JwtDecoder decoder;@MockitoBean CommunityQuestions questions;@MockitoBean CommunityQuestionPolicies policies;
 @BeforeEach void tokens(){when(decoder.decode(anyString())).thenAnswer(c->{String t=c.getArgument(0);return Jwt.withTokenValue(t).header("alg","HS256").subject("1").claim("jti","session").claim("subject_type",t.equals("op")?"operator_account":t.equals("owner")?"user":"staff_account").claim("role",t.equals("op")?"OPERATOR":t.equals("owner")?"OWNER":"MERCHANT").claim("app_id","operator-account").expiresAt(Instant.now().plusSeconds(600)).build();});}
 String body(){return "{\"vehicle_id\":1,\"policy_id\":1,\"policy_revision\":2,\"category\":\"FAULT\",\"message\":\"主动提交的私有文字\",\"consent\":true}";}
 @Test void exactRolesAndSelectorsCannotReachPrivateService()throws Exception{mvc.perform(get("/api/owner/community/questions/cases")).andExpect(status().isUnauthorized());mvc.perform(get("/api/owner/community/questions/cases").header("Authorization","Bearer op")).andExpect(status().isForbidden());mvc.perform(get("/api/admin/community/questions/cases").header("Authorization","Bearer owner")).andExpect(status().isForbidden());for(String q:List.of("owner_id=1","page=1&page=2","page=0","scope=queue"))mvc.perform(get("/api/owner/community/questions/cases?"+q).header("Authorization","Bearer owner")).andExpect(status().isBadRequest());for(String q:List.of("scope=queue&scope=mine","scope=all","page=1&body=true"))mvc.perform(get("/api/admin/community/questions/cases?"+q).header("Authorization","Bearer op")).andExpect(status().isBadRequest());verifyNoInteractions(questions,policies);}
 @Test void exactConfirmedBodyIntegerIdsAndOriginalKeyRequired()throws Exception{for(String b:List.of("{}",body()+"{}",body().replace("\"consent\":true","\"consent\":false"),body().replace("\"category\":\"FAULT\"","\"category\":\"OTHER\""),body().replace("\"vehicle_id\":1","\"vehicle_id\":1.0"),body().replace("\"vehicle_id\":1","\"vehicle_id\":1,\"vehicle_id\":2"))){mvc.perform(post("/api/owner/community/questions/cases").header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isBadRequest());}mvc.perform(post("/api/owner/community/questions/cases").header("Authorization","Bearer owner").contentType(MediaType.APPLICATION_JSON).content(body())).andExpect(status().isBadRequest());mvc.perform(post("/api/owner/community/questions/cases/0/close").header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content("{\"expected_revision\":1}")).andExpect(status().isBadRequest());verifyNoInteractions(questions,policies);}
 @Test void readHasNoStoreSingleEnvelopeAndDependencyFailureIsPrivate()throws Exception{when(questions.context(any())).thenReturn(Map.of("state","UNKNOWN","accepting",false));mvc.perform(get("/api/owner/community/questions/context").header("Authorization","Bearer owner")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.state").value("UNKNOWN"));when(questions.list(any(),eq(true),eq(1))).thenReturn(Map.of("items",List.of()));mvc.perform(get("/api/admin/community/questions/cases?scope=queue").header("Authorization","Bearer op")).andExpect(status().isOk()).andExpect(jsonPath("$.data.items").isArray()).andExpect(header().string("Cache-Control","no-store"));when(questions.detail(any(),eq(1L),eq(1))).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("private body and SQL"));mvc.perform(get("/api/owner/community/questions/cases/1").header("Authorization","Bearer owner")).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value(50300)).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("SQL"))));}
 @Test void replyAssignmentAndPoliciesUseStrictCasInputs()throws Exception{for(String path:List.of("/api/admin/community/questions/cases/1/assignment","/api/admin/community/questions/policies/1/status"))mvc.perform(put(path).header("Authorization","Bearer op").header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content("{\"expected_revision\":1}")).andExpect(status().isBadRequest());mvc.perform(post("/api/admin/community/questions/cases/1/reply").header("Authorization","Bearer op").header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content("{\"expected_revision\":1,\"message\":\"hello\",\"public\":true}")).andExpect(status().isBadRequest());verifyNoInteractions(questions,policies);}
}
